package com.tripsync.entity;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="group_invitations",indexes=@Index(name="idx_invite_token",columnList="token",unique=true))
public class GroupInvitation{@Id private UUID id=UUID.randomUUID();@Column(nullable=false)private UUID groupId;@Column(nullable=false)private String token;private String invitee;@Column(nullable=false)private String role="MEMBER";@Column(nullable=false)private Instant expiresAt;private Instant acceptedAt;@Column(nullable=false)private String status="PENDING";protected GroupInvitation(){}public GroupInvitation(UUID g,String t,String i,Instant e){groupId=g;token=t;invitee=i;expiresAt=e;}public UUID getId(){return id;}public UUID getGroupId(){return groupId;}public String getToken(){return token;}public String getInvitee(){return invitee;}public Instant getExpiresAt(){return expiresAt;}public Instant getAcceptedAt(){return acceptedAt;}public String getStatus(){return status;}public void accept(){status="ACCEPTED";acceptedAt=Instant.now();}}
